"""Shared public request journey. Inputs are rendered by the trusted theme template."""
from html import escape

def select(name, label, options, **attrs):
    extra = ''.join(f' {key}="{escape(str(value), quote=True)}"' for key, value in attrs.items())
    return f'<label for="{name}">{label}</label><select id="{name}" name="{name}"{extra}>' + ''.join(f'<option value="{value}">{text}</option>' for value, text in options) + '</select>'

def build_request_form(services):
    types = [
        ('enquiry','Start a conversation','A question, an idea or a new possibility.'),
        ('consultation','Talk to a specialist','Explore your challenge with our team.'),
        ('software-project','Build a digital product','Move a product or system forward.'),
        ('dedicated-team','Build your team','Find the skills to strengthen delivery.'),
    ]
    choices = ''.join(f'<label class="choice request-choice"><input type="radio" name="request_type" value="{key}" required ' + ('checked ' if key == 'enquiry' else '') + f'><span><strong>{title}</strong><small>{copy}</small></span><i aria-hidden="true">↗</i></label>' for key, title, copy in types)
    common = select('goal','Your main ambition', [('explore','Explore the possibilities'),('modernise','Modernise our technology'),('build','Build a digital product'),('team','Extend our team')])
    common += select('service','Area of interest', [('explore','Let’s work it out together')] + [(s[0],s[1]) for s in services])
    consultation = select('contact_format','Preferred conversation',[('video','Video call'),('phone','Phone call'),('email','Email')])
    consultation += '<label for="timezone">Your time zone</label><input id="timezone" name="timezone" maxlength="80" minlength="2" required placeholder="For example, Europe/London"><label for="availability">When is usually good for you? <span>(optional)</span></label><textarea id="availability" name="availability" maxlength="300" rows="2" placeholder="For example, weekday afternoons in my time zone"></textarea><p class="field-hint">We’ll agree a time with you. This request does not reserve a meeting or create a calendar booking.</p>'
    software = select('project_stage','Where are you starting?',[('idea','An idea to explore'),('prototype','A prototype to develop'),('existing','An existing product or system')])
    software += select('product_type','What would you like to build?',[('other','Let’s work it out together'),('web','Web application'),('mobile','Mobile application'),('platform','Business platform'),('integration','Systems integration')])
    team = '<label for="roles">Which roles or skills do you need?</label><textarea id="roles" name="roles" minlength="3" maxlength="600" required rows="2" placeholder="For example, a Python engineer and a data scientist"></textarea>'
    team += select('team_size','Approximate team size',[('discuss','Help us shape the team'),('1','One specialist'),('2-3','2–3 specialists'),('4-6','4–6 specialists'),('7-plus','7+ specialists')])
    team += select('engagement_length','Expected engagement',[('discuss','To be discussed'),('under-3','Under 3 months'),('3-6','3–6 months'),('6-plus','6+ months')])
    extra = ''.join(f'<fieldset class="request-specific" data-request-fields="{kind}" hidden><legend>{title}</legend>{body}</fieldset>' for kind,title,body in [('consultation','A conversation that fits your day',consultation),('software-project','A little about the product',software),('dedicated-team','The team you have in mind',team)])
    budget = select('budget','Indicative budget (GBP)',[('discuss','To be discussed'),('under-10k','Under £10,000'),('10-25k','£10,000–£25,000'),('25-50k','£25,000–£50,000'),('50-100k','£50,000–£100,000'),('100k-plus','£100,000+')])
    timeline = select('timeline','Ideal start',[('flexible','Flexible / exploring'),('soon','As soon as practical'),('1-3-months','Within 1–3 months'),('3-plus-months','More than 3 months away')])
    return '''<section class="wrap project-layout"><aside><p class="eyebrow">A GOOD CONVERSATION STARTS HERE</p><h2>Big ambition.<br>A simple first step.</h2><p>A new product, a difficult system, a team that needs room to grow. Tell us where you want to go.</p><ol class="contact-steps"><li><span>01</span> Choose your starting point</li><li><span>02</span> Share a few details</li><li><span>03</span> Find a way forward, together</li></ol><div class="request-aside-note"><span class="eyebrow">UK LEADERSHIP / AFRICAN ENGINEERING</span><p>One connected team, from first conversation to practical delivery.</p></div><p class="muted">Please leave out passwords, confidential documents and sensitive personal information.</p></aside><div class="form-card"><div class="demo-note" data-demo-note><span>DESIGN PREVIEW</span> Explore the form using sample details. Nothing is submitted.</div><noscript><p>This guided form needs JavaScript. Enable it to continue.</p></noscript><form id="project-form" novalidate><div class="form-progress" aria-label="Form progress"><span class="current" data-progress="1" aria-current="step">1 <b>Your request</b></span><span data-progress="2">2 <b>About you</b></span><span data-progress="3">3 <b>Review</b></span></div><div class="form-step" data-step="1"><p class="eyebrow">STEP 01 / YOUR STARTING POINT</p><h2>What’s next for you?</h2><fieldset><legend>Choose how we can help</legend><div class="choice-grid">''' + choices + '</div></fieldset><div class="form-row"><div>' + common.split('<label for="service">')[0] + '</div><div><label for="service">' + common.split('<label for="service">')[1] + '</div></div>' + extra + '''<label for="brief">Tell us a little about the challenge</label><textarea id="brief" name="brief" rows="4" minlength="20" maxlength="3000" required placeholder="What are you hoping to achieve, and what stands in your way?"></textarea><p class="field-hint">20–3,000 characters. A short overview is enough.</p><div class="form-row"><div>''' + budget + '</div><div>' + timeline + '''</div></div><button class="button" type="button" data-next>Continue <span aria-hidden="true">→</span></button></div><div class="form-step" data-step="2" hidden><p class="eyebrow">STEP 02 / ABOUT YOU</p><h2>Who should we speak with?</h2><label for="name">Full name</label><input id="name" name="name" autocomplete="name" maxlength="120" required><label for="email">Work email</label><input id="email" name="email" type="email" autocomplete="email" maxlength="190" required><label for="company">Organisation</label><input id="company" name="company" autocomplete="organization" maxlength="190" required><div class="hp" aria-hidden="true"><label for="website">Leave this empty</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><label class="consent"><input type="checkbox" name="consent" value="1" required><span>I agree that SIT Technology may use these details to respond to my request, as described in the <a href="{{url:privacy}}" target="_blank" rel="noopener">privacy notice</a>.</span></label><div class="actions"><button class="button secondary" type="button" data-back>← Back</button><button class="button" type="button" data-next>Review request →</button></div></div><div class="form-step" data-step="3" hidden><p class="eyebrow">STEP 03 / REVIEW</p><h2>Does this look right?</h2><dl class="review-list" id="review-list"></dl><div class="actions"><button class="button secondary" type="button" data-back>← Edit details</button><button class="button" type="submit" id="submit-project">Send request ↗</button></div></div><p id="form-message" class="form-message" role="status" aria-live="polite"></p></form><div id="form-success" hidden tabindex="-1"><span class="success-icon" aria-hidden="true">✓</span><h2>Your next step starts here.</h2><p id="success-copy"></p><button class="button" type="button" id="reset-form">Start again ↗</button></div></div></section>'''
